// Kode akses Tools: admin membuat kode, pembeli memasukkan kode untuk membuka Tools.
// Isi Tools (JavaScript) HANYA dikirim server kalau kode valid.
const crypto = require("crypto");
const U = process.env.UPSTASH_REDIS_REST_URL || process.env.KV_REST_API_URL;
const T = process.env.UPSTASH_REDIS_REST_TOKEN || process.env.KV_REST_API_TOKEN;

async function r(cmd) {
  const x = await fetch(U, {
    method: "POST",
    headers: { Authorization: "Bearer " + T, "Content-Type": "application/json" },
    body: JSON.stringify(cmd),
  });
  const j = await x.json();
  if (j.error) throw new Error(j.error);
  return j.result;
}
const isAdmin = (req) => !!process.env.ADMIN_PASSWORD && req.headers["x-admin-pw"] === process.env.ADMIN_PASSWORD;
const body = (req) => {
  try { return typeof req.body === "string" ? JSON.parse(req.body || "{}") : req.body || {}; } catch (e) { return {}; }
};
const ALPH = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";
const norm = (c) => String(c || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
const pretty = (n) => n.slice(0, 4) + "-" + n.slice(4);
const SESSION = 43200; // sesi tools 12 jam setelah kode dimasukkan
function genCode() {
  const b = crypto.randomBytes(8);
  let s = "";
  for (let i = 0; i < 8; i++) s += ALPH[b[i] % ALPH.length];
  return s;
}
function status(c, now) {
  if (c.exp && now > c.exp) return "kedaluwarsa";
  if (c.max && c.used >= c.max) return "habis";
  return "aktif";
}

module.exports = async (req, res) => {
  res.setHeader("Cache-Control", "no-store");
  if (!U || !T) return res.status(500).json({ error: "database belum tersambung" });
  try {
    const q = req.query || {};
    const now = Date.now();

    // ---- pembeli: kirim isi Tools kalau sesi valid ----
    if (req.method === "GET" && q.op === "js") {
      const tok = String(q.t || "");
      if (!/^[a-f0-9]{16,48}$/.test(tok)) return res.status(401).end();
      const code = await r(["GET", "elztok:" + tok]);
      const raw = code ? await r(["GET", "elzc:" + code]) : null;
      if (!raw) return res.status(401).end();
      const c = JSON.parse(raw);
      if (c.exp && now > c.exp) return res.status(401).end();
      res.setHeader("Content-Type", "application/javascript; charset=utf-8");
      return res.status(200).send("window.ELZ_META=" + JSON.stringify({ label: c.label || "", exp: c.exp || 0 }) + ";\n" + TOOLS_JS);
    }

    // ---- pembeli: masukkan kode ----
    if (req.method === "POST" && body(req).op === "check") {
      const ip = String(req.headers["x-forwarded-for"] || "x").split(",")[0].trim().slice(0, 45).replace(/[^\w.:]/g, "");
      const tries = await r(["INCR", "elzcf:" + ip]);
      if (tries === 1) await r(["EXPIRE", "elzcf:" + ip, 600]);
      if (tries > 12) return res.status(429).json({ ok: false, error: "Terlalu banyak percobaan. Coba lagi 10 menit lagi." });
      const code = norm(body(req).code);
      const raw = code.length === 8 ? await r(["GET", "elzc:" + code]) : null;
      if (!raw) return res.status(403).json({ ok: false, error: "Kode tidak ditemukan." });
      const c = JSON.parse(raw);
      const st = status(c, now);
      if (st === "kedaluwarsa") return res.status(403).json({ ok: false, error: "Kode sudah kedaluwarsa." });
      if (st === "habis") return res.status(403).json({ ok: false, error: "Jatah pemakaian kode ini sudah habis." });
      c.used = (c.used || 0) + 1;
      c.last = now;
      await r(["SET", "elzc:" + code, JSON.stringify(c)]);
      const token = crypto.randomBytes(12).toString("hex");
      await r(["SET", "elztok:" + token, code, "EX", SESSION]);
      return res.status(200).json({ ok: true, token, ttl: SESSION });
    }

    // ---- sisanya khusus admin ----
    if (!isAdmin(req)) return res.status(401).json({ error: "password salah" });

    if (req.method === "GET" && q.op === "list") {
      const ids = (await r(["LRANGE", "elzcodes", 0, 299])) || [];
      const vals = ids.length ? await r(["MGET", ...ids.map((i) => "elzc:" + i)]) : [];
      const codes = vals.filter(Boolean).map((v) => {
        const c = JSON.parse(v);
        return { code: c.code, label: c.label, created: c.created, exp: c.exp, max: c.max, used: c.used || 0, last: c.last || 0, status: status(c, now) };
      });
      return res.status(200).json({ codes });
    }
    if (req.method === "POST" && body(req).op === "create") {
      const b = body(req);
      const n = Math.max(1, Math.min(50, Math.floor(+b.n) || 1));
      const days = Math.max(0, Math.min(3650, Math.floor(+b.days) || 0));
      const max = Math.max(0, Math.min(100000, Math.floor(+b.max) || 0));
      const label = String(b.label || "").slice(0, 40);
      const out = [];
      for (let i = 0; i < n; i++) {
        let code = genCode();
        while (await r(["GET", "elzc:" + code])) code = genCode();
        const rec = { code: pretty(code), label, created: now, exp: days ? now + days * 86400000 : 0, max, used: 0 };
        await r(["SET", "elzc:" + code, JSON.stringify(rec)]);
        await r(["LPUSH", "elzcodes", code]);
        out.push(rec.code);
      }
      await r(["LTRIM", "elzcodes", 0, 999]);
      return res.status(200).json({ ok: true, codes: out });
    }
    if (req.method === "DELETE") {
      const code = norm(body(req).code);
      if (code.length !== 8) return res.status(400).json({ error: "kode tidak valid" });
      await r(["DEL", "elzc:" + code]);
      await r(["LREM", "elzcodes", 0, code]);
      return res.status(200).json({ ok: true });
    }
    return res.status(400).json({ error: "op tidak dikenal" });
  } catch (e) {
    return res.status(500).json({ error: "server error" });
  }
};

